  const now=Date.now(),ip=request.headers.get('CF-Connecting-IP')||'unknown';
  for(const [id,value] of attempts)if(value.until<=now)attempts.delete(id);
  if(attempts.size>=4096&&!attempts.has(ip))return loginPage('Vui lòng thử lại sau vài phút.',429);
  const entry=attempts.get(ip)||{count:0,until:now+600000};if(entry.count>=5)return loginPage('Bạn đã thử nhiều lần. Vui lòng đợi 10 phút.',429);entry.count++;attempts.set(ip,entry);
  const body=await readBody(request);if(body===null)return response('Request too large',413);
  const submitted=new URLSearchParams(body).get('password')||'';
  // Native HMAC verification compares a server-held secret without publishing a password hash.
